output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "Customers are obliged to take the entrance cart before completing their trip.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_rack": "at(1,5)",
        "cart_waiting_at_entry_rack": "cartAt(1,5)"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "at_entry_cart_rack",
              "cart_waiting_at_entry_rack",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "items_must_be_picked_with_cart",
    "text": "Customers are prohibited from picking up shelf items unless they are currently pushing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "not_pushing_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "not_pushing_cart"
            ]
          },
          "post": null
        },
        "cart_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "Customers are prohibited from carrying grocery items by hand rather than using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "cart_not_in_use": {
          "not": "hasCart"
        }
      },
      "events": {
        "hand_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cart_not_in_use"
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "hand_item_pickup"
        ]
      }
    }
  },
  {
    "id": "must_return_cart_to_front",
    "text": "After taking a cart, customers are obliged to return it to the front cart-return area before the trip ends.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_area": "at(0,1)",
        "cart_parked_at_front_return": "cartAt(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "cartAt(1,5)"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_front": {
          "pre": {
            "and": [
              "front_cart_return_area",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "cart_parked_at_front_return",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_front"
    }
  },
  {
    "id": "leave_cart_only_at_front_return",
    "text": "Customers are prohibited from leaving the cart anywhere except the front cart-return area.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_area": "at(0,1)",
        "outside_front_cart_return": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "bad_cart_drop": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_front_cart_return"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "proper_cart_drop": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "front_cart_return_area"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "bad_cart_drop"
    }
  },
  {
    "id": "no_exit_until_cart_returned",
    "text": "Customers are prohibited from exiting unless the cart has been parked at the front return area.",
    "abstraction": {
      "state_properties": {
        "cart_returned_to_front": "cartAt(0,1)",
        "cart_not_returned_to_front": {
          "not": "cartAt(0,1)"
        }
      },
      "events": {
        "exit_without_returning_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_returned_to_front"
            ]
          },
          "post": null
        },
        "exit_after_cart_return": {
          "pre": {
            "and": [
              "EXIT",
              "cart_returned_to_front"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_without_returning_cart"
    }
  },
  {
    "id": "no_cart_through_exit",
    "text": "Customers are prohibited from leaving the store while still pushing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "not_pushing_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        },
        "exit_without_cart": {
          "pre": {
            "and": [
              "EXIT",
              "not_pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_interactions_after_cart_return",
    "text": "Once the cart is parked at the front return area and the customer is no longer pushing it, further store interactions are prohibited.",
    "abstraction": {
      "state_properties": {
        "cart_returned_and_unheld": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "interaction_after_cart_return": {
          "pre": {
            "and": [
              "cart_returned_and_unheld",
              "INTERACT"
            ]
          },
          "post": null
        },
        "front_cart_return": {
          "pre": {
            "and": [
              "at(0,1)",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_and_unheld"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "interaction_after_cart_return"
    }
  }
]
